FUNCTION_BLOCK FB_S11
VAR_INPUT
    SensorCurrent : REAL;
    FallbackValue : REAL;
END_VAR
VAR_OUTPUT
    SensorValid : BOOL := FALSE;
    DegradedMode : BOOL := FALSE;
    ControlValue : REAL := 0.0;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    Initialized : BOOL := FALSE;
    FaultDetected : BOOL;
    InRecoveryBand : BOOL;
    InMeasurementBand : BOOL;
    InvalidScans : UINT := UINT#0;
    RecoveryScans : UINT := UINT#0;
    BlinkScans : UINT := UINT#0;
    WasInvalid : BOOL := FALSE;
    LastMeasuredValue : REAL := 0.0;
END_VAR

(*
需求原文：
温度变送器输出 4—20 mA，需要识别断线并降级运行，
避免因单点故障停机。
1. 4—20 mA 内信号有效，温度为 (电流 - 4) / 16 * 100。
2. 电流 < 3.6 或 > 21 判为断线，持续 2 s 后降级并使用备用值。
3. 重新进入 3.8—20.5 mA 后信号有效，持续 3 s 才允许退出降级。
4. 降级时报警常亮；无效但未降级时报警以 1 Hz 闪烁。
5. 状态：0000 正常，8A01 断线，8A02 降级，8A03 恢复确认。

待审冲突及未明确项：
- C10 要求上电当拍 SensorValid=FALSE、ControlValue=0.0，
  与正常电流当拍立即有效并换算的要求可能冲突。
  本实现保留 C10，上电首拍只建立初态，下一拍开始处理输入。
- C9 要求恢复跳变当拍起连续 150 拍仍保持降级。
  因此第 150 个恢复采样仍降级，第 151 个恢复采样退出。
- 滞回边带的控制数值未定义。本实现只在 4—20 mA 更新测量值，
  其他未降级情况保持最后一次区间内测量值，不外推。
- 无效状态在滞回边带保持；断线计时按连续无效状态累计。
  恢复计时要求电流连续处于 3.8—20.5 mA，离开即清零。
以上边界处理待逐周期测试核对；未声称已编译或验证。
每次调用按固定 20 ms 累计，不使用墙钟时间。
*)

IF NOT Initialized THEN
    SensorValid := FALSE;
    DegradedMode := FALSE;
    ControlValue := 0.0;
    AlarmLamp := FALSE;
    Status := WORD#16#0000;

    InvalidScans := UINT#0;
    RecoveryScans := UINT#0;
    BlinkScans := UINT#0;
    WasInvalid := FALSE;
    LastMeasuredValue := 0.0;
    Initialized := TRUE;
ELSE
    FaultDetected :=
        (SensorCurrent < 3.6) OR (SensorCurrent > 21.0);

    InRecoveryBand :=
        (SensorCurrent >= 3.8) AND (SensorCurrent <= 20.5);

    InMeasurementBand :=
        (SensorCurrent >= 4.0) AND (SensorCurrent <= 20.0);

    (* 滞回：断线阈值优先，中间区域保持有效性状态。 *)
    IF FaultDetected THEN
        SensorValid := FALSE;
    ELSIF InRecoveryBand THEN
        SensorValid := TRUE;
    END_IF;

    IF SensorValid THEN
        InvalidScans := UINT#0;
    ELSE
        IF InvalidScans < UINT#100 THEN
            InvalidScans := InvalidScans + UINT#1;
        END_IF;

        IF InvalidScans >= UINT#100 THEN
            DegradedMode := TRUE;
        END_IF;
    END_IF;

    IF DegradedMode THEN
        IF SensorValid AND InRecoveryBand THEN
            IF RecoveryScans < UINT#151 THEN
                RecoveryScans := RecoveryScans + UINT#1;
            END_IF;

            (* 恢复首拍至第150拍保持降级，随后退出。 *)
            IF RecoveryScans >= UINT#151 THEN
                DegradedMode := FALSE;
                RecoveryScans := UINT#0;
            END_IF;
        ELSE
            RecoveryScans := UINT#0;
        END_IF;
    ELSE
        RecoveryScans := UINT#0;
    END_IF;

    IF SensorValid AND InMeasurementBand THEN
        LastMeasuredValue :=
            ((SensorCurrent - 4.0) / 16.0) * 100.0;
    END_IF;

    (* 降级输出优先，包括恢复确认期。 *)
    IF DegradedMode THEN
        ControlValue := FallbackValue;
    ELSE
        ControlValue := LastMeasuredValue;
    END_IF;

    IF DegradedMode THEN
        AlarmLamp := TRUE;
        BlinkScans := UINT#0;
    ELSIF NOT SensorValid THEN
        (* 50拍一周期：亮25拍、灭25拍；新故障从亮相开始。 *)
        IF NOT WasInvalid THEN
            BlinkScans := UINT#0;
        END_IF;

        AlarmLamp := BlinkScans < UINT#25;

        IF BlinkScans >= UINT#49 THEN
            BlinkScans := UINT#0;
        ELSE
            BlinkScans := BlinkScans + UINT#1;
        END_IF;
    ELSE
        AlarmLamp := FALSE;
        BlinkScans := UINT#0;
    END_IF;

    IF DegradedMode THEN
        IF SensorValid THEN
            Status := WORD#16#8A03;
        ELSE
            Status := WORD#16#8A02;
        END_IF;
    ELSIF NOT SensorValid THEN
        Status := WORD#16#8A01;
    ELSE
        Status := WORD#16#0000;
    END_IF;

    WasInvalid := NOT SensorValid;
END_IF;
END_FUNCTION_BLOCK
